\langle\sigma,\tau\rangle-\langle u,d\tau\rangle&=0,&\tau&\in V^{k-1},\\
\langle d\sigma,v\rangle+\langle du,dv\rangle+\langle p,v\rangle&=\langle f,v\rangle,&v&\in V^k,\\
\langle u,q\rangle&=0,&q&\in\mathsf H^k.
\end{aligned}

